-- Generated by scripts/build-locales.cjs (0.53, roadmap 4.3; split per language in B10); one lookup, no data.
-- The addon's messages are written in English; BackstageForeverTr swaps them for the game's language
-- when a translation exists (machine translations are marked as such in the app), and returns them unchanged
-- otherwise. The texts are in one file per language (BackstageForeverLocaleDe.lua and so on), loaded right
-- after this one; only the file for the game's own language is taken apart.
local L=type(GetLocale)=='function' and GetLocale() or 'enUS'
local plain,patterns={},{}
BackstageForeverLocaleName=L
BackstageForeverTranslated=false
local UNESCAPE={n='\n',r='\r',t='\t',['\\']='\\'}
local function text(s) return (s:gsub('\\(.)',UNESCAPE)) end
-- Called once by each language file. codes: the game locales it serves. Returns true when it was used.
function BackstageForeverLocaleLoad(codes,plainText,patternText)
    local mine=false
    for i=1,type(codes)=='table' and #codes or 0 do if codes[i]==L then mine=true end end
    if not mine or type(plainText)~='string' or type(patternText)~='string' then return false end
    for english,translation in plainText:gmatch('([^\t\n]+)\t([^\n]*)\n') do plain[text(english)]=text(translation) end
    for pattern,replacement in patternText:gmatch('([^\t\n]+)\t([^\n]*)\n') do patterns[#patterns+1]={text(pattern),text(replacement)} end
    BackstageForeverTranslated=next(plain)~=nil or #patterns>0
    return true
end
function BackstageForeverTr(s)
    if type(s)~='string' or s=='' or not BackstageForeverTranslated then return s end
    local v=plain[s]
    if v then return v end
    for i=1,#patterns do
        local p=patterns[i]
        local ok,r,n=pcall(string.gsub,s,p[1],p[2],1)
        if ok and n and n>0 then return r end
    end
    return s
end
